import type { ResultAccessState } from "@prisma/client";
import { prisma } from "@/lib/db/client";
import { getPaymentProvider } from "./index";
import { PaymentError } from "./errors";
import type { PaymentProvider } from "./provider";

const UNLOCK_ELIGIBLE_STATES: ResultAccessState[] = ["LOCKED", "REFERRAL_PENDING", "PAYMENT_PENDING"];
const UNLOCK_AMOUNT_CENTS = 100; // $1, per spec Part 2.2
const CURRENCY = "usd";

/**
 * `clientIdempotencyKey` is generated by the browser, not here — the same
 * key resubmitted (a double-clicked "Pay" button, a retried request) must
 * resolve to the same PaymentIntent, never create two. Backed by two
 * layers: our own `payments.idempotencyKey` unique constraint (checked
 * first, below) and Stripe's own idempotency-key handling on the create
 * call itself (defense in depth — matters if our DB write succeeds but a
 * retry races in before we've persisted it).
 */
export async function createUnlockPaymentIntent(
  userId: string,
  assessmentId: string,
  clientIdempotencyKey: string,
  provider: PaymentProvider = getPaymentProvider(),
): Promise<{ clientSecret: string; paymentId: string }> {
  const existingPayment = await prisma.payment.findUnique({
    where: { idempotencyKey: clientIdempotencyKey },
  });

  if (existingPayment) {
    if (existingPayment.userId !== userId || existingPayment.assessmentId !== assessmentId) {
      throw new PaymentError(
        "idempotency_key_conflict",
        "This idempotency key was already used for a different request",
      );
    }

    const intent = await provider.createPaymentIntent({
      amountCents: existingPayment.amountCents,
      currency: existingPayment.currency,
      idempotencyKey: clientIdempotencyKey,
      metadata: { assessmentId, userId },
    });
    return { clientSecret: intent.clientSecret, paymentId: existingPayment.id };
  }

  const assessment = await prisma.assessment.findUnique({
    where: { id: assessmentId },
    include: { result: true },
  });
  if (!assessment) {
    throw new PaymentError("not_found", "Assessment not found");
  }
  if (assessment.userId !== userId) {
    throw new PaymentError("forbidden", "This assessment does not belong to you");
  }

  const { result } = assessment;
  if (!result) {
    throw new PaymentError("not_submitted", "Complete the assessment before unlocking it");
  }
  if (!UNLOCK_ELIGIBLE_STATES.includes(result.resultAccessState)) {
    throw new PaymentError("already_unlocked", "This result is already unlocked");
  }

  const intent = await provider.createPaymentIntent({
    amountCents: UNLOCK_AMOUNT_CENTS,
    currency: CURRENCY,
    idempotencyKey: clientIdempotencyKey,
    metadata: { assessmentId, userId },
  });

  const payment = await prisma.$transaction(async (tx) => {
    const created = await tx.payment.create({
      data: {
        userId,
        assessmentId,
        provider: "STRIPE",
        providerPaymentId: intent.providerPaymentId,
        amountCents: UNLOCK_AMOUNT_CENTS,
        currency: CURRENCY,
        status: "PENDING",
        idempotencyKey: clientIdempotencyKey,
      },
    });

    // Labeling transition only (mirrors REFERRAL_PENDING) — surfaces "in
    // progress" on the locked-result screen rather than a bare LOCKED
    // while Stripe awaits confirmation.
    if (result.resultAccessState !== "PAYMENT_PENDING") {
      await tx.assessmentResult.update({
        where: { id: result.id },
        data: { resultAccessState: "PAYMENT_PENDING" },
      });
    }

    return created;
  });

  return { clientSecret: intent.clientSecret, paymentId: payment.id };
}
